observation.command:
TOK=$(cat /tmp/kc-token.txt) && UID1=acf1a53a-9e6e-4c76-a983-2dac22d10526 && curl -s -X PUT "http://localhost:8080/admin/realms/my-realm/users/$UID1/reset-password" -H "Authorization: Bearer $TOK" -H "Content-Type: application/json" -d '{"type":"password","value":"user1pass","temporary":false}' -w "set password: HTTP:%{http_code}
" && curl -s -X POST "http://localhost:8080/realms/my-realm/protocol/openid-connect/token" -d "client_id=strassennamen" -d "grant_type=password" -d "username=user1" -d "password=user1pass" -o /tmp/user-token.json -w "user token: HTTP:%{http_code}
" && jq -r .access_token /tmp/user-token.json > /tmp/user-token.txt && echo "$("$jq" -r .access_token /tmp/user-token.txt)" | cut -d. -f2 | tr -d '
' | base64 -d 2>/dev/null | jq -r '.realm_access.roles[], (.resource_access.strassennamen.roles // [])[]'
